		/// Parses `Text` and reads it as `T`: any generated contract type, or a list of one.
		template <typename T>
		bool FromJson(const std::string& Text, T& Out, std::string& Error)
		{
			FJson Json;
			if (!FJson::Parse(Text, Json, Error))
			{
				return false;
			}
			return Read(Json, Out, Error);
		}

		template <typename T>
		std::string ToJson(const T& Value)
		{
			return Write(Value).Dump();
		}
